source /opt/ros/jazzy/setup.bash; source ~/ros2_ws/install/setup.bash; timeout 10 ros2 topic echo --once /aris3/real/state 2>&1 | sed -n '40,100p'; S=/tmp/claude-1000/-home-fc-workspace-team-RobotTeamProject1/55238e22-5fc5-44b8-b9b7-ff6b5eff21d6/scratchpad; mkdir -p $S; cat > $S/grab.py <<'EOF'
"""머리 위 카메라 컬러 한 장과 깊이 한 장을 파일로 저장 (진단용)."""
import sys, rclpy, cv2, numpy as np
from rclpy.qos import qos_profile_sensor_data
from sensor_msgs.msg import CompressedImage
out = sys.argv[1]
rclpy.init(); n = rclpy.create_node('grab_once'); got = {}
def cb(k):
    def f(m): got.setdefault(k, m)
    return f
n.create_subscription(CompressedImage, '/aris3/overhead_camera/image/compressed', cb('c'), qos_profile_sensor_data)
n.create_subscription(CompressedImage, '/aris3/overhead_camera/depth/compressed', cb('d'), qos_profile_sensor_data)
import time; t = time.time()
while len(got) < 2 and time.time() - t < 8: rclpy.spin_once(n, timeout_sec=0.2)
for k, m in got.items():
    open(f'{out}/{k}.bin', 'wb').write(bytes(m.data)); print(k, m.format, len(m.data))
img = cv2.imdecode(np.frombuffer(bytes(got['c'].data), np.uint8), cv2.IMREAD_COLOR)
cv2.imwrite(f'{out}/color.png', img); print(img.shape)
EOF
python3 $S/grab.py $S

